#!/usr/bin/env python3
# SPDX-License-Identifier: AGPL-3.0-or-later
"""Generates src/RECompose.App/Theme/Tokens.g.cs from design/tokens.json.

Usage: python3 tools/tokens/generate.py [--check]
--check exits with 1 if the generated file is out of date (for CI).

Colours become SolidColorBrush resources named after the token ("bg-app") in one theme
dictionary per theme (Dark, Light, High contrast); "color:<name>" holds the Color.
Spacing, radius, size and duration tokens become doubles ("space-4" = 8.0); radii also
become CornerRadius ("radius-m-corner"). Type styles become "type-<name>-size" and
"type-<name>-weight".
"""
import json
import pathlib
import re
import sys

ROOT = pathlib.Path(__file__).resolve().parents[2]
SOURCE = ROOT / "design" / "tokens.json"
TARGET = ROOT / "src" / "RECompose.App" / "Theme" / "Tokens.g.cs"


def avalonia_color(value: str) -> str:
    """CSS #RRGGBB or #RRGGBBAA to Avalonia #RRGGBB or #AARRGGBB."""
    v = value.strip()
    if re.fullmatch(r"#[0-9A-Fa-f]{6}", v):
        return v.upper()
    if re.fullmatch(r"#[0-9A-Fa-f]{8}", v):
        return ("#" + v[7:9] + v[1:7]).upper()
    raise ValueError(f"Unsupported colour {value}")


def resolve(tokens: dict, name: str, theme: str, depth: int = 0) -> str:
    value = tokens[name].get(theme) or tokens[name]["dark"]
    match = re.fullmatch(r"\{([a-z0-9-]+)\}", value)
    if match:
        if depth > 8:
            raise ValueError(f"Reference loop at {name}")
        return resolve(tokens, match.group(1), theme, depth + 1)
    return avalonia_color(value)


def px(value: str) -> float:
    match = re.fullmatch(r"(-?[0-9.]+)(px|ms)?", value.strip())
    if not match:
        raise ValueError(f"Not a length: {value}")
    return float(match.group(1))


def generate() -> str:
    data = json.loads(SOURCE.read_text(encoding="utf-8"))
    themes = [t["id"] for t in data["color"]["themes"]]
    tokens = {t["name"]: t["value"] for t in data["color"]["tokens"]}

    lines = [
        "// <auto-generated>",
        "// Generated by tools/tokens/generate.py from design/tokens.json. Do not edit by hand:",
        "// change the design system, then run the generator.",
        "// </auto-generated>",
        "// SPDX-License-Identifier: AGPL-3.0-or-later",
        "using Avalonia;",
        "using Avalonia.Controls;",
        "using Avalonia.Media;",
        "using Avalonia.Styling;",
        "",
        "namespace RECompose.App.Theme;",
        "",
        "public static class Tokens",
        "{",
        "    /// <summary>The design system's third theme; inherits Dark for anything not overridden.</summary>",
        '    public static readonly ThemeVariant HighContrast = new("HighContrast", ThemeVariant.Dark);',
        "",
        "    private static readonly (string Name, string Dark, string Light, string Contrast)[] Colors =",
        "    [",
    ]
    for name in tokens:
        values = [resolve(tokens, name, theme) for theme in ("dark", "light", "contrast")]
        lines.append(f'        ("{name}", "{values[0]}", "{values[1]}", "{values[2]}"),')
    lines += ["    ];", "", "    private static readonly (string Name, double Value)[] Numbers =", "    ["]

    for group in ("spacing", "radius", "size", "duration"):
        for token in data[group]["tokens"]:
            value = token["value"]
            if isinstance(value, str) and re.fullmatch(r"-?[0-9.]+(px|ms)?", value.strip()):
                lines.append(f'        ("{token["name"]}", {px(value)}),')
    for group in data["type"]["groups"]:
        for style in group["styles"]:
            lines.append(f'        ("type-{style["name"]}-size", {px(style["fontSize"])}),')
            lines.append(f'        ("type-{style["name"]}-weight", {float(style.get("fontWeight", 400))}),')
    lines += [
        "    ];",
        "",
        "    /// <summary>Adds every token to <paramref name=\"resources\"/>.</summary>",
        "    public static void Install(ResourceDictionary resources)",
        "    {",
        "        var dark = new ResourceDictionary();",
        "        var light = new ResourceDictionary();",
        "        var contrast = new ResourceDictionary();",
        "        foreach (var (name, d, l, c) in Colors)",
        "        {",
        "            Add(dark, name, d);",
        "            Add(light, name, l);",
        "            Add(contrast, name, c);",
        "        }",
        "",
        "        resources.ThemeDictionaries[ThemeVariant.Dark] = dark;",
        "        resources.ThemeDictionaries[ThemeVariant.Light] = light;",
        "        resources.ThemeDictionaries[HighContrast] = contrast;",
        "",
        "        foreach (var (name, value) in Numbers)",
        "        {",
        "            resources[name] = value;",
        '            if (name.StartsWith("radius-", System.StringComparison.Ordinal))',
        '                resources[name + "-corner"] = new CornerRadius(value);',
        "        }",
        "    }",
        "",
        "    /// <summary>A token's colour in a theme, for controls that draw themselves.</summary>",
        "    public static Color ColorOf(string name, ThemeVariant? theme)",
        "    {",
        "        foreach (var (n, d, l, c) in Colors)",
        "        {",
        "            if (n != name)",
        "                continue;",
        "            var value = theme == ThemeVariant.Light ? l : theme == HighContrast ? c : d;",
        "            return Color.Parse(value);",
        "        }",
        "",
        "        return Avalonia.Media.Colors.Magenta;",
        "    }",
        "",
        "    private static void Add(ResourceDictionary dictionary, string name, string value)",
        "    {",
        "        var color = Color.Parse(value);",
        '        dictionary["color:" + name] = color;',
        "        dictionary[name] = new SolidColorBrush(color);",
        "    }",
        "}",
        "",
    ]
    return "\n".join(lines)


def main() -> int:
    text = generate()
    if "--check" in sys.argv:
        current = TARGET.read_text(encoding="utf-8") if TARGET.exists() else ""
        if current != text:
            print(f"{TARGET.relative_to(ROOT)} is out of date. Run: python3 tools/tokens/generate.py")
            return 1
        return 0
    TARGET.parent.mkdir(parents=True, exist_ok=True)
    TARGET.write_text(text, encoding="utf-8")
    print(f"Wrote {TARGET.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
